import{_ as a}from"./chunks/projects-sidebar-colors.DIY830dX.js";import{_ as r,a as t,b as o}from"./chunks/weiteres-beispiel.Chd7zmRi.js";import{_ as s,o as i,c as n,a3 as l}from"./chunks/framework.BlfGB29P.js";const v=JSON.parse('{"title":"Sidebar Colors","description":"Individual colors and opacity for HA sidebar entries in the native editor. HACS and Marketplace, DE/EN/FR.","frontmatter":{"title":"Sidebar Colors","description":"Individual colors and opacity for HA sidebar entries in the native editor. HACS and Marketplace, DE/EN/FR."},"headers":[],"relativePath":"en/projects/sidebar-colors/index.md","filePath":"en/projects/sidebar-colors/index.md","lastUpdated":1794652120000}'),d={name:"en/projects/sidebar-colors/index.md"};function c(p,e,h,m,u,g){return i(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="sidebar-colors" tabindex="-1">Sidebar Colors <a class="header-anchor" href="#sidebar-colors" aria-label="Permalink to &quot;Sidebar Colors&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">HA 2026.11: selector fixed</p><p>Version <strong>0.1.1</strong> supports both <code>ha-md-list-item</code> and <code>ha-list-item-button</code> in the native edit dialog. All 27 local tests pass, including DOM regressions for both HA row types, opacity, Cancel, Save, reopening and theme reset. The corresponding Manager fix was live-tested on .177; Sidebar Colors was not additionally installed alongside it. Existing colors and storage keys are preserved.</p></div><p><a href="/en/collection/ha-2026-11-compatibility">Scope, results and remaining findings</a>.</p><img src="'+a+'" width="80" height="80" alt="Sidebar Colors"><p><strong>0.1.1 · Frontend extension · DE / EN / FR · MIT</strong></p><p>Give each Home Assistant sidebar entry its own icon and label color. The new color field is placed directly in <strong>Edit sidebar</strong>, between the name and the eye control. Visibility and order remain controlled by the familiar native controls.</p><p><a href="https://github.com/rockbaer2007/ha-sidebar-colors" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://github.com/rockbaer2007/ha-sidebar-colors/releases/latest" target="_blank" rel="noreferrer">Download / Releases</a> · <a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=rockbaer2007&amp;repository=ha-sidebar-colors&amp;category=plugin" target="_blank" rel="noreferrer">Open in HACS</a></p><h2 id="color-picker" tabindex="-1">Color picker <a class="header-anchor" href="#color-picker" aria-label="Permalink to &quot;Color picker&quot;">​</a></h2><p>Saturation/brightness area, hue slider, HEX input and opacity with live preview. The checkerboard represents transparency. <strong>Apply</strong> closes the picker; only <strong>Save</strong> in the HA dialog persists the change. <strong>Cancel</strong> discards the corresponding color draft. <strong>Theme color</strong> removes that entry’s override.</p><p><img src="'+r+'" alt="ATLAS color picker with 70 percent opacity"></p><h2 id="user-examples" tabindex="-1">User examples <a class="header-anchor" href="#user-examples" aria-label="Permalink to &quot;User examples&quot;">​</a></h2><p>The screenshots show individually chosen icon and text colors. Identical display names remain distinct through their panel paths. There is no enforced palette.</p><div class="sidebar-color-examples"><figure><a href="/images/sidebar-colors/beispiel.png" target="_blank" rel="noopener noreferrer"><img src="'+t+'" alt="Colored sidebar with Overview, ATLAS and HACS"></a><figcaption>First result with individually chosen colors.</figcaption></figure><figure><a href="/images/sidebar-colors/weiteres-beispiel.png" target="_blank" rel="noopener noreferrer"><img src="'+o+`" alt="Additional example with ATLAS tools and Zigbee2MQTT"></a><figcaption>Another configuration including ATLAS tools.</figcaption></figure></div><h2 id="requirements-and-verification" tabindex="-1">Requirements and verification <a class="header-anchor" href="#requirements-and-verification" aria-label="Permalink to &quot;Requirements and verification&quot;">​</a></h2><p>Intended minimum: <strong>Home Assistant Core 2026.10.3</strong>. Real tests on <strong>2026.10.4</strong> covered color selection, 70% and 0% opacity, preview, Save/Cancel, reload, theme reset, two-tab synchronization and native visibility/reorder controls. The user confirmed the result. The temporary test color was removed; their own colors were retained.</p><p>The minimum follows the available interfaces, not a separate live test on 2026.10.3. Marketplace starting with <strong>2026.11</strong> uses the same HACS-compatible package format; no separate runtime test there is claimed. <a href="https://contributors.home-assistant.io/marketplace/how-it-works/" target="_blank" rel="noreferrer">Official Marketplace description</a></p><h2 id="install-with-hacs-marketplace" tabindex="-1">Install with HACS / Marketplace <a class="header-anchor" href="#install-with-hacs-marketplace" aria-label="Permalink to &quot;Install with HACS / Marketplace&quot;">​</a></h2><p>Create a full HA backup first. This is a <strong>frontend plugin</strong>, not a Supervisor app or a card to add to a dashboard. It is initially available as a custom repository; publication does not automatically add it to the default catalog.</p><ol><li>In HACS, add <code>https://github.com/rockbaer2007/ha-sidebar-colors</code> through <strong>Custom repositories</strong>, category <strong>Dashboard</strong> (<code>plugin</code>), then download <strong>Sidebar Colors</strong>.</li><li>Starting with 2026.11, use the corresponding custom-repository flow under <strong>Settings → Marketplace</strong>. Marketplace carries over HACS settings; no separate migration format is required.</li><li>Extend the existing <code>frontend:</code> section. Preserve existing themes and extra modules; do not add a duplicate section:</li></ol><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">frontend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  extra_module_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/hacsfiles/ha-sidebar-colors/ha-sidebar-colors.js</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ol start="4"><li>Check the configuration, restart HA and reload the browser. A dashboard resource alone is insufficient when opening a non-dashboard page first. The module entry also loads the extension there.</li><li>Hold the <strong>Home Assistant</strong> sidebar heading and click a color field.</li></ol><h2 id="manual-installation-or-migration" tabindex="-1">Manual installation or migration <a class="header-anchor" href="#manual-installation-or-migration" aria-label="Permalink to &quot;Manual installation or migration&quot;">​</a></h2><p>Copy the single <code>ha-sidebar-colors.js</code> release file to <code>/config/www/ha-sidebar-colors.js</code> and use <code>/local/ha-sidebar-colors.js</code> as the module instead. The release ZIP contains the same file, license and documentation. Do not load both installation paths simultaneously.</p><p>For the older three-file prototype, replace <code>/local/ugso-sidebar-colors/0.1.0/sidebar-colors.js</code> with the new module path, restart HA and reload the browser. The color storage stays the same; old files may remain as a backup.</p><h2 id="preserve-settings-and-update" tabindex="-1">Preserve settings and update <a class="header-anchor" href="#preserve-settings-and-update" aria-label="Permalink to &quot;Preserve settings and update&quot;">​</a></h2><p>Colors are stored per HA user under the separate key <code>ugso_sidebar_colors_v1</code> and synchronized on devices with the extension loaded. Panel paths, rather than names, prevent collisions. A colors-only save does not overwrite native order, hidden entries or theme settings. Dashboard configuration and permissions are unchanged.</p><p>Before saving, one previous snapshot of colors and sidebar preferences is kept locally under <code>ugso-sidebar-colors-backup:&lt;user-id&gt;</code>. This does not replace a full HA backup. Full or blocked browser storage prevents saving. No new credentials, external scripts or cloud translation are required.</p><p>Update from the same HACS/Marketplace repository, preserve the module path and reload the browser. To uninstall, remove only the module entry, restart HA and reload. Theme colors return while native settings are retained.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><p>The extension hooks internal HA dialog methods and must be rechecked after frontend upgrades. Conflicts or uncertain acknowledgements keep the draft open; writes are not blindly retried. This user-data API has no atomic compare-and-save. Colors and native order are separate operations, with checked best-effort compensation on failure.</p><p>At 0% opacity, icon and text can be invisible, but the color field stays accessible. Selection background, titles and access control remain unchanged. Failure/conflict tests were simulated locally; no real phone/tablet test or induced Marketplace network failure is claimed. <a href="https://github.com/rockbaer2007/ha-sidebar-colors/blob/main/docs/TESTING.md" target="_blank" rel="noreferrer">Verification details and source</a>.</p>`,31)])])}const y=s(d,[["render",c]]);export{v as __pageData,y as default};
